package com.opensocket.aievent.gateway.netty.admin;
import static org.assertj.core.api.Assertions.*;import java.time.*;import org.junit.jupiter.api.Test;import tools.jackson.databind.json.JsonMapper;import com.opensocket.aievent.gateway.netty.config.AdminProperties;import com.opensocket.aievent.gateway.netty.configuration.*;
class V41C3R2NAdminRuntimeConfigurationViewTest{
 @Test void snapshotOverridesStartupAndKeepsInitialDelayStartupOnly(){var p=new AdminProperties();p.setMetricsPushEnabled(false);p.setMetricsPushIntervalMs(5000);p.setMetricsPushInitialDelayMs(7000);p.setRecentEventLimit(100);var r=new GatewayRuntimeConfigurationLocalRegistry();var v=new GatewayRuntimeConfigurationSnapshotValues(r,JsonMapper.builder().build());var view=new AdminRuntimeConfigurationView(p,v);assertThat(view.metricsPushEnabled()).isFalse();r.atomicSwap(s("{\"admin.metrics-push-enabled\":true,\"admin.metrics-push-interval-ms\":2000,\"admin.recent-event-limit\":500}"));assertThat(view.metricsPushEnabled()).isTrue();assertThat(view.metricsPushInterval()).isEqualTo(Duration.ofSeconds(2));assertThat(view.recentEventLimit()).isEqualTo(500);assertThat(view.metricsPushInitialDelay()).isEqualTo(Duration.ofSeconds(7));}
 private static GatewayRuntimeConfigurationSnapshot s(String p){var n=OffsetDateTime.now(ZoneOffset.UTC);return new GatewayRuntimeConfigurationSnapshot("LOCAL","admin",AdminRuntimeConfigurationView.SET_KEY,"r-n",1,8,n,n.plusHours(1),"GATEWAY",p,"hash","sig");}
}
